function mint() external payable returns (uint256 tokenId) {
    if (msg.value != 0) revert NotFree();
    if (AGENT_ID.balanceOf(msg.sender) == 0) revert NotAgentIdHolder();
    if (hasMinted[msg.sender]) revert AlreadyMinted();
    hasMinted[msg.sender] = true;
    tokenId = _mintTo(msg.sender);

/// @notice Creator reserve, max 33 tokens in total (including the 2 minted at deploy).
function creatorMint(address to, uint256 qty) external onlyOwner {
    if (creatorMinted + qty > CREATOR_RESERVE) revert ReserveExceeded();
    creatorMinted += qty;
    for (uint256 i; i < qty; ++i) _mintTo(to);
}

/// @notice Owner can change the royalty receiver; rate is capped at 5%.
function setRoyalty(address receiver, uint96 bps) external onlyOwner {
    require(bps <= 500, "max 5%");
    _setDefaultRoyalty(receiver, bps);

function freeMint() external {
    require(!paused, "paused");
    string memory handle = AGENT_ID.handleOf(msg.sender);
    require(bytes(handle).length > 0, "no Agent ID");
    bytes32 key = keccak256(bytes(handle));
    require(!handleClaimed[key], "Agent ID used");
    require(!walletClaimed[msg.sender], "wallet used");
    handleClaimed[key] = true;
    walletClaimed[msg.sender] = true;
    uint256 id = _mintOne(msg.sender);
    emit FreeClaimed(msg.sender, handle, id);
}

function mint(uint256 quantity) external payable {
    require(!paused, "paused");
    require(quantity > 0 && quantity <= MAX_PER_TX, "bad quantity");
    require(msg.value == quantity * PRICE, "wrong value");
    for (uint256 i; i < quantity; ++i) _mintOne(msg.sender);
    (bool ok, ) = treasury.call{value: msg.value}("");
    require(ok, "treasury transfer failed");

function canFreeMint(address wallet) external view returns (bool) {
    if (paused || totalSupply >= MAX_SUPPLY || walletClaimed[wallet]) return false;
    try AGENT_ID.handleOf(wallet) returns (string memory h) {
        return bytes(h).length > 0 && !handleClaimed[keccak256(bytes(h))];
    } catch { return false; }
}

function setPaused(bool p) external onlyOwner { paused = p; }

function mint(uint256 agentId, uint256 quantity) external nonReentrant {
    if (block.timestamp < startTime) revert NotStarted();
    if (agentIds.ownerOf(agentId) != msg.sender) revert NotAgentOwner();
    if (quantity == 0) revert BadQuantity();
    uint256 done = mintedBy[agentId];
    if (done + quantity > PER_AGENT) revert AgentQuotaExceeded();
    if (publicMinted + quantity > publicSupply) revert SoldOut();

    uint256 cost = priceFor(agentId, quantity);
    usdt.safeTransferFrom(msg.sender, address(this), cost);

function priceFor(uint256 agentId, uint256 quantity) public view returns (uint256 cost) {
    uint256 done = mintedBy[agentId];
    for (uint256 i; i < quantity; ++i) {
        cost += (done + i < CHEAP_COUNT) ? PRICE_LOW : PRICE_HIGH;
    }

function burnForPower(uint256 id) external nonReentrant {
    address holder = _requireOwned(id);
    if (!_isAuthorized(holder, msg.sender, id)) revert NotAuthorized();
    Info storage f = _info[id];
    if (f.tier == 0 && !_reveal(id)) revert NotRevealed();
    if (f.team && publicMinted < publicSupply) revert TeamLocked();

    uint256 p = powerForTier(f.tier);
    _settle(holder);
    powerOf[holder] += p;
    totalPower += p;
    _debt[holder] = powerOf[holder] * accPerPower;

    _burn(id);
    totalBurned += 1;
    emit Burned(holder, id, f.tier, p);

/// @notice Claim USDT rewards earned by your Power.
function claim() external nonReentrant {
    _settle(msg.sender);
    uint256 amount = _owed[msg.sender] / ACC;
    if (amount == 0) revert NothingToClaim();
    _owed[msg.sender] -= amount * ACC;
    rewardsOut += amount;
    usdt.safeTransfer(msg.sender, amount);
    emit Claimed(msg.sender, amount);

function quote(address minter, uint256 paid) public view returns (uint256 tokens, uint256 cost, bool getsFree) {
    getsFree = !freeClaimed[minter];
    uint256 a = paidCount[minter];
    (uint256 j, uint256 r, uint256 d) = _bonus(a, a + paid);
    tokens = (getsFree ? 1 : 0) + paid + j + r + d;
    cost = paid * PRICE;
}

/// One call: claims the free Pixel Pup if not yet claimed, plus `paid` Pixel Kitties (paid may be 0)
function mint(uint256 paid) external payable {
    if (block.timestamp >= mintEnd) revert MintClosed();
    if (AGENT_ID.balanceOf(msg.sender) == 0) revert NotAgent();
    uint256 a = paidCount[msg.sender];
    if (a + paid > MAX_PAID_PER_WALLET) revert WalletLimit();
    (uint256 tokens, uint256 cost, bool getsFree) = quote(msg.sender, paid);
    if (tokens == 0) revert NothingToMint();
    if (totalSupply + tokens > MAX_SUPPLY) revert SoldOut();
    if (msg.value != cost) revert WrongPayment();

uint256 id = totalSupply;
if (getsFree) {
    freeClaimed[msg.sender] = true;
    ++freeMinted;
    id = _mintOne(msg.sender, id, 0);
}
for (uint256 k; k < paid; ++k) id = _mintOne(msg.sender, id, 1);
paidCount[msg.sender] = a + paid;

id = _mintBonus(msg.sender, id, a, a + paid);

_balances[msg.sender] += tokens;
totalSupply = id;

function _mintBonus(address to, uint256 id, uint256 a, uint256 z) private returns (uint256) {
    (uint256 j, uint256 r, uint256 d) = _bonus(a, z);
    if (j > 0) { for (uint256 k; k < j; ++k) id = _mintOne(to, id, 2); emit Milestone(to, 10, j); }
    if (r > 0) { for (uint256 k; k < r; ++k) id = _mintOne(to, id, 3); emit Milestone(to, 20, r); }
    if (d > 0) { for (uint256 k; k < d; ++k) id = _mintOne(to, id, 4); emit Milestone(to, 30, d); }
    bonusMinted += j + r + d;

function currentPrice() public view returns (uint256) {
    uint256 tier = totalSupply / TIER_SIZE; // 0..3
    if (tier == 0) return 0.0008 ether;
    if (tier == 1) return 0.0014 ether;
    if (tier == 2) return 0.0020 ether;
    return 0.0026 ether;

function mint() external payable returns (uint256 tokenId) {
    if (AGENT_ID.balanceOf(msg.sender) == 0) revert NoAgentId();
    if (hasMinted[msg.sender]) revert AlreadyMinted();
    if (totalSupply >= MAX_SUPPLY) revert SoldOut();

    uint256 price = currentPrice();
    if (msg.value < price) revert Underpaid(price);

    // effects
    hasMinted[msg.sender] = true;
    tokenId = ++totalSupply;
    _ownerOf[tokenId] = msg.sender;
    unchecked { _balanceOf[msg.sender] += 1; }
    emit Transfer(address(0), msg.sender, tokenId);
    emit SoulMinted(msg.sender, tokenId, price);

    // interactions
    soul.mint(msg.sender, SOUL_PER_MINT);
    (bool ok, ) = TREASURY.call{value: price}("");
    require(ok, "treasury transfer failed");
    if (msg.value > price) {
        (bool r, ) = payable(msg.sender).call{value: msg.value - price}("");
        require(r, "refund failed");

function bnbUsd() public view returns (uint256) {
    (, int256 answer, , uint256 updatedAt, ) = BNB_USD.latestRoundData();
    require(answer > 0, "bad price");
    require(block.timestamp - updatedAt <= MAX_PRICE_AGE, "stale price");
    return uint256(answer); // 8 decimals
}

/// @notice exact BNB (wei) needed for `amount` paid tokens right now
function quoteMint(uint256 amount) public view returns (uint256) {
    uint256 p = bnbUsd();
    return (amount * currentUsdPrice() * 1e8 + p - 1) / p;
}

function freeLeft(uint256 agentTokenId, address wallet) public view returns (uint256) {
    uint256 a = FREE_PER_AGENT - freeClaimedByAgent[agentTokenId];
    uint256 w = FREE_PER_AGENT - freeClaimedByWallet[wallet];
    uint256 n = a < w ? a : w;
    uint256 s = (MAX_SUPPLY - totalSupply) / 1 ether;
    return n < s ? n : s;

function claimFree(string calldata agentName) external returns (uint256) {
    return _claim(uint256(keccak256(bytes(agentName))));
}

function claimFreeById(uint256 agentTokenId) external returns (uint256) {
    return _claim(agentTokenId);
}

function _claim(uint256 id) internal returns (uint256 n) {
    require(isOpen(), "minting closed");
    require(AGENT_ID.ownerOf(id) == msg.sender, "not your Agent ID");
    n = freeLeft(id, msg.sender);
    require(n > 0, "free quota used");
    freeClaimedByAgent[id] += n;
    freeClaimedByWallet[msg.sender] += n;
    _mint(msg.sender, n * 1 ether);
    emit AgentClaim(msg.sender, id, n);
}

function mint(uint256 amount) external payable {
    require(isOpen(), "minting closed");
    require(amount >= 1 && amount <= MAX_PAID_PER_TX, "amount 1-10000");
    require(AGENT_ID.balanceOf(msg.sender) > 0, "need .ai Agent ID");
    uint256 cost = quoteMint(amount);
    require(msg.value >= cost, "send >= quoteMint(amount)");
    require(totalSupply + amount * 1 ether <= MAX_SUPPLY, "sold out");

receive() external payable {
    _mintFor(msg.sender, quantityFor(msg.sender, msg.value), msg.value);
}

function _mintFor(address who, uint256 quantity, uint256 paid) internal nonReentrant {
    if (finalized) revert AlreadyFinalized();
    if (refundForced) revert MintCancelled();
    if (paused) revert MintPaused();
    if (block.timestamp < mintStart) revert NotStarted();
    if (block.timestamp >= mintEnd) revert MintEnded();
    _requireAgentId(who);
    if (mintedOf[who] >= MAX_PER_ID) revert CapReached();
    if (quantity == 0) revert WrongAmount();
    uint256 total = totalMinted + quantity;
    // the airdrop's room is reserved until it has been pushed out
    if (total + (airdropCogs - airdropMinted) > PUBLIC_COGS) revert SoldOut();
    totalMinted = total;
    mintedOf[who] += quantity;
    paidOf[who] += paid;
    totalPaid += paid;
    cog.mint(who, quantity);
    emit Minted(who, quantity, paid, total);
}

function withdrawTeam() external nonReentrant {
    if (msg.sender != team) revert NotTeam();
    if (finalized) revert AlreadyFinalized();
    if (refundOpen()) revert RefundsOpen();
    uint256 amount = totalPaid * (BPS - LP_BPS) / BPS - teamDrawn;
    if (amount == 0) revert NothingToWithdraw();
    uint256 drawn = teamDrawn + amount;
    teamDrawn = drawn;
    if (!_send(team, amount)) revert TransferFailed();
    emit TeamWithdrawn(amount, drawn);
}

function refundOf(address who) public view returns (uint256) {
    uint256 paid = paidOf[who];
    if (paid == 0) return 0;
    return paid * (totalPaid - teamDrawn) / totalPaid;
}

function refundOpen() public view returns (bool) {
    if (finalized) return false;
    if (refundForced) return true;
    if (block.timestamp < mintEnd) return false;
    return totalMinted < PUBLIC_COGS || block.timestamp >= mintEnd + FINALIZE_WINDOW;
}

function finalize() external nonReentrant {
    if (finalized) revert AlreadyFinalized();
    if (refundForced) revert MintCancelled();
    if (totalMinted < PUBLIC_COGS) revert NotSoldOut();
    if (block.timestamp >= mintEnd + FINALIZE_WINDOW) revert FinalizeWindowClosed();
    finalized = true;

    address pair = IGearzToken(address(token)).pair();
    uint256 bnb = address(this).balance;
    // the pool gets 80% of everything paid in, including what the team already took; the team gets the rest
    uint256 toLp = (bnb + teamDrawn) * LP_BPS / BPS;
    uint256 toTeam = bnb - toLp;
    uint256 tokens = token.balanceOf(address(this));

    // Mint on the pair directly, not through the router: WBNB pre-loaded into the pair by someone cannot block it
    token.safeTransfer(pair, tokens);
    IWBNB(wbnb).deposit{value: toLp}();
    if (!IWBNB(wbnb).transfer(pair, toLp)) revert TransferFailed();
    uint256 liquidity = IPancakePair(pair).mint(DEAD);

    uint64 miningStart = uint64(block.timestamp + MINING_DELAY);
    mining.start(miningStart);
    cog.scheduleReveal();

    teamOwed = toTeam;
    _payTeam();
    emit Finalized(pair, toLp, tokens, liquidity, toTeam, miningStart);
}

function workHash(address miner, uint256 nonce, bytes32 previous, bytes32 anchor) public view returns (bytes32) {
    return keccak256(abi.encodePacked(block.chainid, address(this), miner, nonce, previous, anchor));
}

function mine(uint256 nonce, uint256 anchorBlock, bytes32 expectedPrevWork)
    external
    payable
    nonReentrant
    returns (uint256 id)
{
    if (block.timestamp < mintStartsAt) revert MintNotOpen(mintStartsAt);
    if (agentRegistry.balanceOf(msg.sender) == 0) revert NotVerifiedAgent();
    if (totalMinted != 0 && block.timestamp < lastMintAt + MIN_MINT_INTERVAL) {
        revert MintTooSoon(lastMintAt + MIN_MINT_INTERVAL);
    }
    uint256 price = mintPrice();
    if (msg.value != price) revert InvalidPayment();
    if (
        totalMinted >= MAX_SUPPLY || expectedPrevWork != prevWork || anchorBlock >= block.number
            || block.number - anchorBlock > 128
    ) revert InvalidWork();

    bytes32 anchor = blockhash(anchorBlock);
    bytes32 work = workHash(msg.sender, nonce, prevWork, anchor);
    uint256 target = effectiveTarget();
    if (anchor == bytes32(0) || uint256(work) >= target) revert InvalidWork();

    uint256 alive = totalSupply();
    uint256 rent = price * 70 / 100;
    uint256 protocolFee = price * 15 / 100;
    uint256 vaultFee = price - rent - protocolFee;

    pendingRent += rent;
    if (alive != 0) {
        accPerDroid += pendingRent * SCALE / alive;
        pendingRent = 0;
    }

    id = ++totalMinted;
    claimedAcc[id] = accPerDroid;
    seedOf[id] = keccak256(abi.encode(work, id));
    prevWork = work;

    if (target > currentTarget) {
        currentTarget = target;
        windowStart = block.timestamp;
        windowMints = 0;
    } else if (++windowMints == 8) {
        uint256 elapsed = block.timestamp - windowStart;
        elapsed = elapsed < 80 ? 80 : elapsed > 320 ? 320 : elapsed;
        currentTarget = Math.mulDiv(currentTarget, elapsed, 160);
        currentTarget = currentTarget < HARDEST_TARGET
            ? HARDEST_TARGET
            : currentTarget > EASIEST_TARGET ? EASIEST_TARGET : currentTarget;
        windowStart = block.timestamp;
        windowMints = 0;
    }
    lastMintAt = block.timestamp;

    totalProtocolFeesPaid += protocolFee;
    (bool sentProtocol,) = protocolTreasury.call{value: protocolFee}("");
    require(sentProtocol, "Protocol fee transfer failed");

    (bool sentVault,) = address(buybackRouter).call{value: vaultFee}("");
    require(sentVault, "Vault fee transfer failed");

    _safeMint(msg.sender, id);
    emit Mined(id, msg.sender, seedOf[id]);
}

function burn(uint256 id) external nonReentrant {
    if (ownerOf(id) != msg.sender) revert Unauthorized();
    require(buybackRouter.bootstrapped(), "Community pool not launched");
    uint256 rent = claimableRent(id);
    uint256 reward = burnReward();
    _burn(id);
    delete claimedAcc[id];
    burnedCount++;
    hdroidToken.mintReward(msg.sender, reward);
    if (rent != 0) {
        (bool ok,) = msg.sender.call{value: rent}("");
        require(ok, "Rent transfer failed");
    }
    emit RentRedeemed(id, msg.sender, rent);
    emit Burned(id, reward);
}

function buyWithAuthorization(Authorization calldata auth, Limits calldata limits, uint256 deadline)
    external
    nonReentrant
    returns (BuyResult memory r)
{
    if (msg.sender != relayer) revert NotRelayer();
    if (block.timestamp > deadline) revert BadParams();
    r = _buy(auth, limits);
}

function buyBatch(Authorization[] calldata auths, Limits[] calldata limits, uint256 deadline)
    external
    nonReentrant
    returns (bool[] memory ok, BuyResult[] memory results)
{
    if (msg.sender != relayer) revert NotRelayer();
    uint256 n = auths.length;
    if (block.timestamp > deadline || n == 0 || n > MAX_BATCH || limits.length != n) revert BadParams();
    ok = new bool[](n);
    results = new BuyResult[](n);
    for (uint256 i; i < n; i++) {
        if (gasleft() < MIN_ITEM_GAS) revert BatchGasTooLow(i, gasleft());
        try this.buyOne(auths[i], limits[i]) returns (BuyResult memory r) {
            ok[i] = true;
            results[i] = r;
        } catch (bytes memory reason) {
            emit BatchItemFailed(i, auths[i].from, auths[i].nonce, reason);
        }

function _buy(Authorization calldata auth, Limits calldata limits) internal returns (BuyResult memory) {
    _claim(auth.from, auth.nonce);
    uint256 usdFloor = USD.balanceOf(address(this)); // any U already here is someone else's stranded payment — must not be touched
    IERC3009(address(USD)).transferWithAuthorization(
        auth.from, address(this), PRICE, auth.validAfter, auth.validBefore, auth.nonce, auth.v, auth.r, auth.s
    );
    return _distribute(auth.from, limits, usdFloor);

function settleStranded(address from, bytes32 nonce, Limits calldata limits, uint256 deadline)
    external
    nonReentrant
    returns (BuyResult memory r)
{
    if (msg.sender != relayer) revert NotRelayer();
    if (block.timestamp > deadline) revert BadParams();
    if (!IERC3009(address(USD)).authorizationState(from, nonce)) revert AuthorizationNotUsed();
    _claim(from, nonce);

    uint256 stranded = USD.balanceOf(address(this));
    if (stranded < PRICE) revert NoStrandedPayment(stranded, PRICE);
    r = _distribute(from, limits, stranded - PRICE);

function _claim(address from, bytes32 nonce) internal {
    if (lpTokenId == 0) revert NotSeeded();
    if (!lpReady()) revert LpNotApproved(lpTokenId);
    if (from == address(0)) revert BadParams();
    if (address(AGENT_ID) != address(0) && AGENT_ID.balanceOf(from) == 0) revert NotAgentWallet(from);
    if (settled[from][nonce]) revert AlreadySettled(from, nonce);
    settled[from][nonce] = true;
}

/// @param usdFloor U balance this contract must return to after the order (only stranded payments may remain).
function _distribute(address buyer, Limits calldata limits, uint256 usdFloor)
    internal
    returns (BuyResult memory r)
{
    uint256 inventory = TOKEN.balanceOf(address(this));
    if (inventory < 2 * SHARE) revert SoldOut(inventory, 2 * SHARE);

    salesSettled += 1;
    usdProcessed += PRICE;
    TOKEN.safeTransfer(buyer, SHARE);
